#!/usr/bin/env node
import * as fs from 'fs';
import * as path from 'path';
import yargs from 'yargs';
import { hideBin } from 'yargs/helpers';

interface Arguments {
  folderPath: string;
}

function calculateFolderSize(folderPath: string): number {
  let totalSize = 0;

  function traverse(currentPath: string): void {
    try {
      const stats = fs.statSync(currentPath);

      if (stats.isFile()) {
        totalSize += stats.size;
      } else if (stats.isDirectory()) {
        const entries = fs.readdirSync(currentPath);
        for (const entry of entries) {
          traverse(path.join(currentPath, entry));
        }
      }
    } catch (error) {
      // Silently skip files/folders that can't be accessed
    }
  }

  traverse(folderPath);
  return totalSize;
}

const argv = yargs(hideBin(process.argv))
  .command('$0 <folderPath>', 'Calculate folder size recursively', (yargs) => {
    return yargs.positional('folderPath', {
      describe: 'Path to the folder',
      type: 'string',
      demandOption: true
    });
  })
  .help()
  .strict()
  .parseSync() as Arguments;

const size = calculateFolderSize(argv.folderPath);
console.log(`FOLDER_SIZE_BYTES=${size}`);

